 1	// A router with no framework, so the project has an HTTP surface to survey
 2	// in Chapter 1's rate-limiting example without an Express dependency.
 3	import { listActiveUsers, findUser } from '../services/user-service.js';
 4	import { listOrdersForUser, totalPaidCents } from '../services/order-service.js';
 5	import { uncapturedTotalCents } from '../services/payment-service.js';
 6	
 7	export const routes = [
 8	  { method: 'GET', path: '/users', handler: (req, cb) => listActiveUsers(cb) },
 9	  { method: 'GET', path: '/users/:id', handler: (req, cb) => findUser(Number(req.params.id), cb) },
10	  { method: 'GET', path: '/users/:id/orders', handler: (req, cb) => listOrdersForUser(Number(req.params.id), cb) },
11	  { method: 'GET', path: '/reports/paid-total', handler: (req, cb) => totalPaidCents(cb) },
12	  { method: 'GET', path: '/reports/uncaptured-total', handler: (req, cb) => uncapturedTotalCents(cb) },
13	];
14	
15	export function listEndpoints() {
16	  return routes.map((r) => `${r.method} ${r.path}`);
17	}
18	import { query } from '../db.js';
19	
20	export class OrderRepository {
21	  findByUser(userId) {
22	    return new Promise((resolve, reject) => {
23	      query('orders', (o) => o.user_id === userId && o.deleted_at === null,
24	        (err, rows) => (err ? reject(err) : resolve(rows)));
25	    });
26	  }
27	
28	  findPaid() {
29	    return new Promise((resolve, reject) => {
30	      query('orders', (o) => o.status === 'paid' && o.deleted_at === null,
31	        (err, rows) => (err ? reject(err) : resolve(rows)));
32	    });
33	  }
34	}
35	import { query } from '../db.js';
36	
37	// Callback-style database access. Chapter 5 migrates this to OrderRepository.
38	export function listOrdersForUser(userId, callback) {
39	  query('orders', (o) => o.user_id === userId && o.deleted_at === null, callback);
40	}
41	
42	export function totalPaidCents(callback) {
43	  query('orders', (o) => o.status === 'paid' && o.deleted_at === null, (err, rows) => {
44	    if (err) return callback(err);
45	    callback(null, rows.reduce((sum, o) => sum + o.total_cents, 0));
46	  });
47	}

